style.css:
/* Fondo general */
html, body {
    background-color: #f8d7e5 !important;
}

/* Texto */
body, span, div {
    color: #d63384 !important;
}

/* Barra superior */
header {
    background-color: #ff8fc1 !important;
}

/* Sidebar */
nav {
    background-color: #f3c6d9 !important;
}

/* Botones */
button {
    background-color: #ff69b4 !important;
    color: white !important;
}

/* Inputs */
input, textarea {
    background-color: #ffe4f1 !important;
    color: #d63384 !important;
}
